// A run-56 purchase day's fill-draw craps battle, read from chain and rebuilt in a worker.
//
// COIN_DRAW_BATTLE (run 56 only) plays the whole battle inside the day's jackpot call and logs one
// run per drawn wallet plus a pot. From run 57 (audit 0889affc1) the daily jackpot battle is a
// craps-table field instead, replayed by chain/craps.js; this reader refuses it. Nothing is stored, so the day's
// settlement window and its recorded word are the complete input: the worker derives the battle
// word, recovers the chip and replays every run, and refuses to return a replay any logged figure
// disagrees with. A refused replay still returns the chain's own results (`replay: null`).
import { chainClient, ChainDataError, checkAbort, compareLogs } from './client.js';
import { eventFacts } from './facts.js';
import { settlementWindow, battleEvents, coinDrawBattleKey, BATTLE_RUN, BATTLE_POT } from './jackpots.js';
import { jackpotBattleKey, isRun56Schema } from './schema.js';
import { keccak256 } from '../vendor/ethers-app.mjs';

const jobs = new Map();
// A replay that has not answered by now never will (a worker that failed to start can
// stay silent); settle it so the battle's OPEN never spins forever.
const REPLAY_WORKER_TIMEOUT_MS = 30_000;

/** The day's fill-draw events and word, all from one snapshot. */
export async function loadCoinDrawInputs(s, day, signal) {
  if (!isRun56Schema()) throw new ChainDataError('The jackpot battle plays at the craps table.', 'NOT_FOUND');
  const window = await settlementWindow(s, day, signal);
  if (!window.start) throw new ChainDataError('This day has no recorded word yet.', 'REPLAY_PENDING');
  const contract = jackpotBattleKey();
  const rows = (await eventFacts(s, battleEvents(), { contract, fromBlock: window.fromBlock, toBlock: window.toBlock, signal }))
    .filter(row => compareLogs(row, window.start) > 0 && (!window.end || compareLogs(row, window.end) < 0));
  const runs = rows.filter(row => BATTLE_RUN.has(row.name));
  if (!runs.length) throw new ChainDataError('This day played no fill-draw battle.', window.seal ? 'NOT_FOUND' : 'REPLAY_PENDING');
  // resolve() emits every run and the pot in the one call that plays them.
  const tx = runs[0].transactionHash; const level = Number(runs[0].args.level);
  if (rows.some(row => row.transactionHash !== tx || Number(row.args.level) !== level)) {
    throw new ChainDataError('The fill-draw battle spans more than one call.', 'INCOMPLETE_HISTORY');
  }
  const pot = rows.find(row => BATTLE_POT.has(row.name)) ?? null;
  const pinned = s.client.chain.codeHashes?.[contract];
  if (pinned) {
    const runtime = keccak256(await s.client.atBlock('eth_getCode', [s.client.address(contract)], s, signal));
    if (runtime !== pinned) throw new ChainDataError('The jackpot battle runtime does not match the deployment manifest.', 'DEPLOYMENT_NOT_READY');
  }
  await s.verify(signal);
  return { key: coinDrawBattleKey(day), day, level, dayWord: String(window.start.args.finalWord), transactionHash: tx,
    blockNumber: Number(runs[0].blockNumber), blockHash: runs[0].blockHash,
    runs: runs.map(row => ({ player: row.args.player, units: String(row.args.units), bankrollOut: String(row.args.bankrollOut),
      rolls: String(row.args.rolls), paid: String(row.args.paid) })),
    pot: pot ? { winner: pot.args.winner, pot: String(pot.args.pot) } : null };
}

function workerReplay(input) {
  if (typeof Worker === 'undefined') return import('./coin-draw-worker.js').then(({ materializeCoinDrawBattle }) => materializeCoinDrawBattle(input));
  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL('./coin-draw-worker.js', import.meta.url), { type: 'module' });
    const timer = setTimeout(() => {
      worker.terminate();
      reject(new ChainDataError('The battle replay took too long. Try again.', 'REPLAY_TIMEOUT'));
    }, REPLAY_WORKER_TIMEOUT_MS);
    worker.onmessage = ({ data }) => {
      clearTimeout(timer);
      worker.terminate();
      if (data.error) reject(Object.assign(new ChainDataError(data.error, 'REPLAY_MISMATCH'), { replayCode: data.code }));
      else resolve(data.replay);
    };
    worker.onerror = event => { clearTimeout(timer); worker.terminate(); reject(new ChainDataError(event.message || 'Fill-draw replay worker failed.')); };
    worker.postMessage(input);
  });
}

async function buildCoinDrawBattle(client, day, replay) {
  const s = await client.snapshot({ fresh: true });
  const input = await loadCoinDrawInputs(s, day);
  try {
    return { ...input, replay: await replay(input), replayError: null };
  } catch (error) {
    if (error?.code !== 'REPLAY_MISMATCH') throw error;
    // Fail closed on the dice, not on the page: the chain's results stand without a replay.
    return { ...input, replay: null, replayError: error.message };
  }
}

/**
 * The day's fill-draw battle: chain results plus, when every figure reproduces, the replayed runs.
 * Cached per deployment and day; a reorg of the battle's block rebuilds it.
 */
export async function chainCoinDrawBattle(day, { signal, client = chainClient(), replay = workerReplay } = {}) {
  checkAbort(signal);
  const cacheKey = `${client.chain.id}:${client.address(jackpotBattleKey())}:${Number(day)}`;
  let job = jobs.get(cacheKey);
  if (job?.result && (await client.header(job.result.blockNumber, signal)).hash !== job.result.blockHash) { jobs.delete(cacheKey); job = null; }
  if (job?.error && Date.now() - job.at > 15_000) { jobs.delete(cacheKey); job = null; }
  if (!job) {
    job = { at: Date.now() };
    job.promise = buildCoinDrawBattle(client, Number(day), replay).then(value => { job.result = value; }, error => { job.error = error; });
    jobs.set(cacheKey, job);
    for (const oldKey of jobs.keys()) if (jobs.size > 4 && oldKey !== cacheKey) jobs.delete(oldKey);
  }
  await job.promise; checkAbort(signal);
  if (job.error) throw job.error;
  return job.result;
}

/** Test seam. */
export function __resetCoinDrawJobsForTest() { jobs.clear(); }
